             & \phantom{={}}\sum_{j=1}^p (-1)^{j+1} \tbinom{p}{j} \norm{\vek{s}}_2^{-2j} P_{\sym} \Paren{\Paren{\otimes^j \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}}[\vek{s}]                                                                                                                                                \\
            \begin{split}
                {} = \sum_{j=1}^p (-1)^{j+1} \norm{\vek{s}}_2^{-2j} \bigg( \tbinom{p-1}{j-1} P_{\sym} \Paren{\Paren{\otimes^{j-1} \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}} \norm{\vek{s}}_2^2 \phantom{\bigg)}\\
