A \emph{\(p\)-tensor} \(\tns{T}\) of dimensions \(n_1 \times \dots \times n_p\) is a multilinear map \(\R^{n_1} \times \dots \times \R^{n_p}\to \R\), so that its evaluation
\begin{equation}
    \tns{T}[\vek{s}_1, \dots, \vek{s}_p], \quad \vek{s}_i \in \R^{n_i}
\end{equation}
is linear in each component.
We refer to these \(p\) components as the \emph{modes} of the tensor and denote the space of such \(p\)-tensors by \(\R^{n_1 \otimes \dots \otimes n_p}\).
If \(n_1 = \dots = n_p = n\) the space is denoted \(\R^{\otimes^p n}\) and \(\tns{T}[\vek{s}, \dots, \vek{s}]\) is abbreviated as \(\tns{T}[\vek{s}]^p\).
The notation also allows to apply the tensor to \(q < p\) vectors, which then results in a \((p-q)\)-tensor.

Moreover, we define the application of matrices \(\mat{W}_1, \dots, \mat{W}_p\) of appropriate dimensions to a tensor by
\begin{equation}
    \big(\tns{T}[\mat{W}_1, \dots, \mat{W}_p]\big)[\vek{s}_1, \dots, \vek{s}_p] = \tns{T}[\mat{W}_1 \vek{s}_1, \dots, \mat{W}_p \vek{s}_p].
\end{equation}

For any \(\tns{T} \in \R^{\otimes^p n}\) and any permutation \(\sigma \in S_p\), let \(\sigma(\tns{T}) \in \R^{\otimes^p n}\) be defined by
\begin{equation}
    \sigma(\tns{T})[\vek{s}_1, \dots, \vek{s}_p] = \tns{T}[\vek{s}_{\sigma(1)}, \dots, \vek{s}_{\sigma(p)}].
\end{equation}
If \(\sigma(\tns{T}) = \tns{T}\) for all \(\sigma \in S_p\), then \(\tns{T}\) is called \emph{symmetric}.
The space of all symmetric \(p\)-tensors is denoted \(\R^{\otimes^p n}_{\sym}\).

The projection of \(\R^{\otimes^p n}\) onto \(\R^{\otimes^p n}_{\sym}\) is given by
\begin{equation}
    P_{\sym}(\tns{T}) = \frac{1}{p!} \sum_{\sigma \in S_p} \sigma(\tns{T}),
\end{equation}
see \cite[Proposition 3.76]{hackbusch_tensor_2012}.

Just like matrices, tensors are fully characterized by their actions on basis vectors.
This can be used to represent a \(p\)-tensor \(\tns{T} \in \R^{\otimes^p n}\) as a \(p\)-dimensional array \((t_{i_1, \dots, i_p})_{1 \leq i_j \leq n, 1 \leq j \leq p}\) where
\begin{equation}
    t_{i_1, \dots, i_p} = \tns{T}[\vek{e}_{i_1}, \dots, \vek{e}_{i_p}] \quad \text{and} \quad \tns{T} = \sum_{i_1, \dots, i_p = 1}^n t_{i_1, \dots, i_p} \vek{e}_{i_1} \otimes \dots \otimes \vek{e}_{i_p}.
\end{equation}

Another norm is the one induced by the 2-norm on \(\R^n\) (Hackbusch \cite{hackbusch_tensor_2012} calls it the injective norm) which is defined by
\begin{equation}
    \norm{\tns{T}}_2 = \max_{\norm{\vek{s}_i}_2 = 1,\, 1 \leq i \leq p} \abs{\tns{T}[\vek{s}_1, \dots, \vek{s}_p]}.
\end{equation}

As for matrices, the 2-norm is bounded by the Frobenius norm:
\begin{equation}
    \norm{\tns{T}}_2
    % = \max_{\norm{\vek{s}_i}_2 = 1,\, 1 \leq i \leq p} \abs{\tns{T}[\vek{s}_1, \dots, \vek{s}_p]}
    = \max_{\norm{\vek{s}_i}_2 = 1,\, 1 \leq i \leq p} \abs{\innerprod{\tns{T}}{\vek{s}_1 \otimes \dots \otimes \vek{s}_p}_F}
    \leq \norm{\tns{T}}_F.
\end{equation}
In the last inequality we used Cauchy-Schwarz and the fact that \(\norm{\vek{s}_1 \otimes \dots \otimes \vek{s}_p}_F = 1\) if all \(\vek{s}_i\) have unit 2-norm.

As for matrices, the 2-norm is bounded by the Frobenius norm:
\begin{equation}
    \norm{\tns{T}}_2
    % = \max_{\norm{\vek{s}_i}_2 = 1,\, 1 \leq i \leq p} \abs{\tns{T}[\vek{s}_1, \dots, \vek{s}_p]}
    = \max_{\norm{\vek{s}_i}_2 = 1,\, 1 \leq i \leq p} \abs{\innerprod{\tns{T}}{\vek{s}_1 \otimes \dots \otimes \vek{s}_p}_F}
    \leq \norm{\tns{T}}_F.
\end{equation}
In the last inequality we used Cauchy-Schwarz and the fact that \(\norm{\vek{s}_1 \otimes \dots \otimes \vek{s}_p}_F = 1\) if all \(\vek{s}_i\) have unit 2-norm.

We will denote the approximations to \(D^p f(\vek{x}_k)\) by \(\tns{C}_k \in \R^{\otimes^p n}_{\sym}\) and the true \(p\)th derivative averaged over all points on the line from \(\vek{x}_k\) to \(\vek{x}_{k+1}\) by
\begin{equation}\label{eqn:C-tilde-definition}
    \widetilde{\tns{C}}_k = \int_0^1 D^p f(\vek{x}_k + t \vek{s}_k) \diff t  \in \R^{\otimes^p n}_{\sym}.
\end{equation}

The \(p\)th-order analogue of the secant equation \cref{eqn:short-secant-equation} is given by
\begin{equation}\label{eqn:generalized-secant-equation}
    \tns{C}_{k+1} [\vek{s}_k] = D^{p-1} f(\vek{x}_{k+1}) - D^{p-1} f(\vek{x}_k) = \widetilde{\tns{C}}_k [\vek{s}_k]
\end{equation}

and the generalized update formula for \(\tns{C}_k\) reads
\begin{equation}\label{eqn:update-definition}
    \tns{C}_{k+1} = \argmin_{\tns{C} \in \R^{\otimes^p n}_{\sym}} \norm{(\tns{C} - \tns{C}_k)[\mat{W}_k]^p}_F \text{ s.t. } \tns{C}[\vek{s}_k] = \widetilde{\tns{C}}_k[\vek{s}_k]. \tag{HOSU}
\end{equation}

