    Because \(\binom{p-1}{p} = 0\) the only remaining term is the symmetric projection of \((\widetilde{\tns{C}} - \tns{C}_{\bullet})[\vek{s}]\).
    Property \cref{eqn:update-minimum-property} follows from a similar consideration to the one above.
    If \(\vek{u}_1, \dots, \vek{u}_p\) are all orthogonal to \(\vek{s}\), then
    \begin{equation}
        P_{\sym} \Paren{\Paren{\otimes^j \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}}[\vek{u}_1, \dots, \vek{u}_p] = 0
    \end{equation}
    for \(j \geq 1\) because no matter how the outer product is oriented there is always a factor of \(\vek{s}^T \vek{u}_i = 0\) in the result.

    For \labelcref{item:characterization-low-rank} we need to show that we can always write the update in the form \(P_{\sym}(\tns{A} \otimes \vek{s})\) for some symmetric \((p-1)\)-tensor \(\tns{A}\) and that \(\tns{A}\) is unique such that the corresponding update satisfies the secant equation \cref{eqn:update-secant-equation}.
    Note that the expression for the update in \labelcref{item:characterization-explicit} is already of the form \(P_{\sym}(\tns{A} \otimes \vek{s})\):
    \begin{subequations}
        \begin{align}
             & \phantom{={}}\sum_{j=1}^p (-1)^{j+1} \tbinom{p}{j} \norm{\vek{s}}_2^{-2j} P_{\sym} \Paren{\Paren{\otimes^j \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}}                               \\
             & = P_{\sym} \Paren{ P_{\sym} \Paren{ \sum_{j=1}^p (-1)^{j+1} \tbinom{p}{j} \norm{\vek{s}}_2^{-2j} \Paren{\otimes^{j-1} \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j} } \otimes \vek{s} }
        \end{align}
    \end{subequations}
    It remains to show that among all updates of the form \(P_{\sym}(\tns{A} \otimes \vek{s})\) there is only one choice of \(\tns{A} \in \R^{\otimes^p n}_{\sym}\) such that \cref{eqn:update-secant-equation} holds.
    Consider the linear map
    \begin{align*}
        \phi \colon \R^{\otimes^{p-1} n}_{\sym} & \to \R^{\otimes^{p-1} n}_{\sym}                    \\
        \tns{A}                                 & \mapsto P_{\sym}(\tns{A} \otimes \vek{s})[\vek{s}]
    \end{align*}
    which maps a finite-dimensional vector space to itself.
    Combining what we already showed for \labelcref{item:characterization-explicit} with the observation that the update in \labelcref{item:characterization-explicit} is of the desired form, this map is surjective (we can prescribe any \((\widetilde{\tns{C}} - \tns{C}_{\bullet})[\vek{s}]\)) and so it must be bijective, which shows uniqueness of \(\tns{A}\).

    Lastly, \labelcref{item:characterization-recursive} claims that the update can be written as
    \begin{equation}
        \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}} - \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}} \Brack{\mat{I} - \frac{\vek{s} \vek{s}^T}{\norm{\vek{s}}_2^2}}^p.
    \end{equation}
    Clearly, property \cref{eqn:update-secant-equation} is satisfied because applying this tensor to \(\vek{s}\) makes the second term vanish, leaving only the desired result.
    Moreover, for any vector \(\vek{u}\) that is orthogonal to \(\vek{s}\) the matrix \(\mat{I} - \frac{\vek{s} \vek{s}^T}{\norm{\vek{s}}_2^2}\) maps \(\vek{u}\) to itself.
    This means applying the tensor above to \(\vek{u}_1, \dots, \vek{u}_p\), all of which are orthogonal to \(\vek{s}\), will give zero because both terms cancel out.
    This is property \cref{eqn:update-minimum-property}.

    Now that the equivalence has been established for \(\mat{W} = \mat{I}\), we consider the general case where \(\mat{W} \in \R^{n \times n}\) is any nonsingular matrix.
    The minimization in \labelcref{item:characterization-min-frobenius}
    \begin{equation}
        \tns{C}_+ = \argmin_{\tns{C} \in \R^{\otimes^p n}_{\sym}} \norm{(\tns{C} - \tns{C}_{\bullet})[\mat{W}]^p}_F \text{ s.t. } \tns{C}[\vek{s}] = \widetilde{\tns{C}}[\vek{s}]
    \end{equation}
    can be rewritten using \(\tns{D}_{\bullet} = \tns{C}_{\bullet}[\mat{W}]^p\), \(\widetilde{\tns{D}} = \widetilde{\tns{C}}[\mat{W}]^p\), \(\tns{D}_+ = \tns{C}_+[\mat{W}]^p\) and \(\vek{r} = \mat{W}^{-1}\vek{s}\) as
    \begin{equation}
        \tns{D}_+ = \argmin_{\tns{D} \in \R^{\otimes^p n}_{\sym}} \norm{\tns{D} - \tns{D}_{\bullet}}_F \text{ s.t. } \tns{D}[\vek{r}] = \widetilde{\tns{D}}[\vek{r}].
    \end{equation}
    Applying the existing characterizations and the fact that \(\tns{C}_+ = \tns{D}_+[\mat{W}^{-1}]^p\) we get the claim after some algebraic manipulations.
\end{proof}

The first characterization can be rewritten as
\begin{equation}\label{eqn:general-psb-update}
    \tns{C}_+ = \tns{C}_{\bullet} + \argmin_{\tns{U} \in \R^{\otimes^p n}_{\sym}} \norm{\tns{U}}_F \text{ s.t. } \tns{U}[\vek{s}] = (\widetilde{\tns{C}} - \tns{C}_{\bullet})[\vek{s}].
\end{equation}

Therefore, there is a unique solution to the minimization problem in \labelcref{item:characterization-min-frobenius}, and it is fully characterized by the fact that the update tensor \(\tns{U} = \tns{C}_+ - \tns{C}_{\bullet}\) is symmetric and satisfies the following two properties:
\begin{subequations}
    \begin{align}
        \tns{U}[\vek{s}]                     & = \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}] \label{eqn:update-secant-equation}        \\
        \tns{U}[\vek{u}_1, \dots, \vek{u}_p] & = 0 \text{ if all } \vek{u}_i \text{ are orthogonal to } \vek{s} \label{eqn:update-minimum-property}
    \end{align}
\end{subequations}
We will use this as the basis to show the equivalence with all other characterizations.

In \labelcref{item:characterization-explicit} we claim that the update \(\tns{U}\) has the form
\begin{equation}
    \sum_{j=1}^p (-1)^{j+1} \tbinom{p}{j} \norm{\vek{s}}_2^{-2j} P_{\sym} \Paren{\Paren{\otimes^j \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}}
\end{equation}
This tensor is clearly symmetric since it is a sum of symmetric tensors.

To show that it satisfies property \cref{eqn:update-secant-equation} consider
\begin{subequations}\label{eqn:update-explicit-cancellation}
    \begin{align}
         & \phantom{={}}\sum_{j=1}^p (-1)^{j+1} \tbinom{p}{j} \norm{\vek{s}}_2^{-2j} P_{\sym} \Paren{\Paren{\otimes^j \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}}[\vek{s}]                                                                                                                                                \\
        \begin{split}
            {} = \sum_{j=1}^p (-1)^{j+1} \norm{\vek{s}}_2^{-2j} \bigg( \tbinom{p-1}{j-1} P_{\sym} \Paren{\Paren{\otimes^{j-1} \vek{s}} \otimes \paren{\widetilde{\tns{C}} - \tns{C}_{\bullet}}[\vek{s}]^{j}} \norm{\vek{s}}_2^2 \phantom{\bigg)}\\
